const dateHeading=document.querySelector('.card-heading .eyebrow');dateHeading.textContent='The Date';const dateOrnament=document.createElement('img');dateOrnament.className='date-ornament';dateOrnament.src='krishna-wedding-ornament.svg';dateOrnament.alt='';document.querySelector('.card-heading').after(dateOrnament);const instruction=document.createElement('p');instruction.className='date-instruction';instruction.textContent='✦ Scratch to reveal the date ✦';dateOrnament.after(instruction);
const invitation=document.getElementById('invitation');invitation.insertAdjacentHTML('beforeend',`<article class="invitation-frame section-reveal"><img class="devotional-art" src="radha-krishna-devotional.svg" alt="Radha and Krishna in an ornate gold temple arch"><p class="blessing-verse" lang="hi">॥ श्री राधाकृष्णाय नमः ॥</p><img class="invitation-divider" src="krishna-wedding-ornament.svg" alt=""><div class="couple-monogram" aria-label="Dhiraj and Neha">DN</div><p class="formal-intro">With the blessings of our elders,<br>you are invited to the wedding of</p><h2 class="formal-name">Dhiraj</h2><p class="family-label">SON OF</p><p class="family-placeholder">Shri Rajesh Yadav<br>&amp; Smt Parvati Yadav</p><p class="with-word">with</p><h2 class="formal-name">Neha</h2><p class="family-label">DAUGHTER OF</p><p class="family-placeholder">Shri Kanhiyalal Yadav<br>&amp; Smt Suman Yadav</p><p class="formal-date">Wednesday, 2nd December 2026</p><p class="formal-venue" lang="hi">ग्राम – कनकपुर (नयेपुर)<br>पोस्ट – भोरी, जिला – भदोही<br>उत्तर प्रदेश</p></article><section class="invitation-block section-reveal"><h2>Our story</h2><img class="invitation-divider" src="krishna-wedding-ornament.svg" alt=""><p class="story-copy">Together, we begin a new chapter.<br>Join us as we celebrate our wedding<br>with your love and blessings.</p><p class="missing-note">[Your personal story will appear here.]</p></section><section class="invitation-block section-reveal"><h2>Us, so far</h2><img class="invitation-divider" src="krishna-wedding-ornament.svg" alt=""><div class="photo-scroll" aria-label="Couple photographs"><figure class="memory"><div class="memory-photo photo-placeholder"><span aria-hidden="true">❧</span><div>[Couple photograph]</div></div><figcaption>Dhiraj &amp; Neha</figcaption></figure><figure class="memory"><div class="memory-photo photo-placeholder"><span aria-hidden="true">❧</span><div>[Add another couple photograph]</div></div><figcaption>More memories to come</figcaption></figure></div><p class="missing-note">Swipe to see more →</p></section><p class="invitation-end" lang="hi">आप सभी सादर आमंत्रित हैं।</p>`);
const revealSections=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('shown');revealSections.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.section-reveal').forEach(el=>revealSections.observe(el));

const monogram=document.querySelector('.couple-monogram');monogram.innerHTML='<img src="dn-monogram-art.svg" alt="Dhiraj and Neha intertwined gold monogram">';
const preweddingPortraits=[['courtyard','Golden hour, together'],['lakeside','A quiet moment'],['garden','A little laughter'],['palace','An evening to remember']];document.querySelector('.photo-scroll').innerHTML=preweddingPortraits.map(([name,caption])=>`<figure class="memory"><div class="memory-photo"><img src="prewedding-${name}.png" alt="Generated pre-wedding portrait of Dhiraj and Neha — ${caption}" loading="lazy" decoding="async" width="1024" height="1536"></div><figcaption>${caption}</figcaption></figure>`).join('');
