const galleryMask=document.createElement('div');galleryMask.innerHTML='<svg width="0" height="0" style="position:absolute" aria-hidden="true"><defs><clipPath id="memory-arch-curve" clipPathUnits="objectBoundingBox"><path d="M .075 .935 L .075 .365 C .075 .295 .13 .255 .205 .238 C .205 .19 .26 .157 .365 .15 C .365 .117 .415 .095 .463 .085 Q .488 .073 .5 .054 Q .512 .073 .537 .085 C .585 .095 .635 .117 .635 .15 C .74 .157 .795 .19 .795 .238 C .87 .255 .925 .295 .925 .365 L .925 .935 Z"/></clipPath></defs></svg>';document.body.append(galleryMask);
document.querySelector('.photo-scroll').innerHTML=[1,2,3].map((n)=>`<figure class="memory"><div class="memory-photo"><img src="couple-memory-${n}.jpeg" alt="Dhiraj and Neha together, photograph ${n}" loading="lazy" decoding="async" class="supplied-memory memory-${n}"></div><figcaption>Dhiraj &amp; Neha</figcaption></figure>`).join('');
